(function(){
'use strict';
const e=v=>App.e(v==null?'':v),ico=(n,s=20)=>App.icon(n,s),ui=()=>App.ui,state=()=>Demo.state;
const metrics={hz:{label:'输出频率',unit:'Hz',digits:1,color:'#15e4ef'},current:{label:'输出电流',unit:'A',digits:1,color:'#15e4ef'},voltage:{label:'输出电压',unit:'V',digits:0,color:'#15e4ef'},bus:{label:'母线电压',unit:'V',digits:0,color:'#15e4ef'}};
const run=d=>!d.online?'unknown':d.run===true?'running':d.run===false?'stopped':'unknown';
const runText=d=>({running:'运行中',stopped:'已停止',unknown:'状态未知'})[run(d)];
const finite=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
const number=(v,n=1)=>finite(v)?Number(v).toFixed(n):'—';
const effective=id=>typeof Demo.effectiveContract==='function'?Demo.effectiveContract(id):Demo.contract(id);
const owner=d=>{const c=effective(d.id),u=c&&Demo.user(c.ownerId);return u?u.name:c?'客户资料待同步':'待出租';};
const chronological=items=>items.slice().sort((a,b)=>Date.parse(b.createdAt||b.time)-Date.parse(a.createdAt||a.time));
const time=v=>v?App.time(v):'未提供';
const shortTime=v=>{if(!v)return '—';try{return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(v));}catch{return '—';}};
const regions=()=>[...new Set(state().devices.map(d=>d.region||'未分类'))];
const selected=()=>state().devices.find(d=>d.id===ui().deviceId)||state().devices[0];
const count=ds=>({total:ds.length,running:ds.filter(d=>run(d)==='running').length,stopped:ds.filter(d=>run(d)==='stopped').length,unknown:ds.filter(d=>run(d)==='unknown').length,fault:ds.filter(d=>!!d.fault).length,offline:ds.filter(d=>!d.online).length});
function button(text,attrs='',cls=''){return '<button type="button" class="mp-button '+cls+'" '+attrs+'>'+text+'</button>';}
function pill(text,tone=''){return '<span class="mp-pill '+tone+'"><i></i>'+e(text)+'</span>';}
function section(title,extra=''){return '<div class="mp-section-title"><h2>'+e(title)+'</h2><span></span>'+extra+'</div>';}
function motor(){return '<svg class="mp-motor" viewBox="0 0 100 88" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="3.5" stroke-linejoin="round"><rect x="25" y="18" width="48" height="49" rx="4"/><path d="M25 25H13v34h12M73 29h13v26H73M37 18V7h23v11M32 67v11M65 67v11M25 78h50M33 28h32M33 38h32M33 48h32M33 58h32"/><path d="M7 32h6v19H7" stroke-width="2.5"/></g></svg>';}
function tree(){
 const active=ui().monitorRegion||'all',expanded=ui().monitorTreeExpanded||{};
 return '<aside class="mp-region-tree" data-mp-region-tree>'+section('区域分类')+'<div class="mp-tree-root">'+button(ico('chevron-down',18)+'<span>海南省</span><strong>'+state().devices.length+'</strong>','data-mon-region="all"',active==='all'?'selected':'')+'</div><div class="mp-tree-list">'+regions().map(region=>{
  const total=state().devices.filter(d=>(d.region||'未分类')===region).length,open=Object.prototype.hasOwnProperty.call(expanded,region)?expanded[region]:active===region;
  return '<div class="mp-tree-group"><div class="mp-tree-row '+(active===region?'selected':'')+'">'+button(ico(open?'chevron-down':'chevron-right',18),'data-mp-expand="'+e(region)+'" aria-label="'+(open?'收起':'展开')+e(region)+'" aria-expanded="'+open+'"','mp-tree-toggle')+button('<span>'+e(region)+'</span><strong>'+total+'</strong>','data-mon-region="'+e(region)+'"','mp-tree-choice')+'</div>'+(open?'<div class="mp-tree-children">'+button(ico('corner-down-right',15)+'<span>乡镇待映射</span><small>'+total+'</small>','data-mon-region="'+e(region)+'"','mp-tree-child')+'</div>':'')+'</div>';
 }).join('')+'</div><div class="mp-tree-note">'+ico('info',16)+'行政层级按已登记资料展示，未提供乡镇信息的设备归入待映射。</div></aside>';
}
function card(d){
 const headline=d.fault?'故障':!d.online?'离线':runText(d),tone=d.fault?'fault':!d.online?'offline':run(d)==='running'?'running':'stopped';
 return '<button type="button" class="mp-device-card '+tone+'" data-mon-detail="'+e(d.id)+'" data-mon-card="'+e(d.id)+'"><div class="mp-card-top">'+motor()+'<div class="mp-card-identity"><strong>'+e(d.name)+'</strong><span>'+e(d.id)+'</span></div></div><div class="mp-card-state">'+pill(headline,tone)+'<small>'+e(d.online?'通信在线 · '+runText(d):'通信离线 · 运行状态未知')+'</small></div><dl class="mp-card-info"><dt>所属人</dt><dd>'+e(owner(d))+'</dd><dt>位置</dt><dd title="'+e(d.region+' · '+d.place)+'">'+e(d.region||'未分类')+' · '+e(d.place||'位置未登记')+'</dd></dl></button>';
}
function regional(){
 const region=ui().monitorRegion||'all',query=(ui().monitorSearch||'').trim().toLowerCase(),online=ui().monitorOnline||'all',status=ui().monitorRun||'all';
 const districtCandidate=globalThis.MapLevels?.nodes?.[String(ui().monitorDistrictCode||'')],district=districtCandidate?.level==='district'&&globalThis.MapLevels.nodes[districtCandidate.parent]?.name===region?districtCandidate:null;
 if(!district)ui().monitorDistrictCode='';
 const scoped=state().devices.filter(d=>(region==='all'||(d.region||'未分类')===region)&&(!district||typeof d.districtCode==='string'&&d.districtCode===district.code)),stats=count(scoped);
 const filtered=scoped.filter(d=>(!query||[d.id,d.name,d.model,d.module,d.region,d.place,owner(d)].join(' ').toLowerCase().includes(query))&&(online==='all'||(online==='online'?d.online:!d.online))&&(status==='all'||(status==='fault'?!!d.fault:status==='offline'?!d.online:run(d)===status))).sort((a,b)=>a.id.localeCompare(b.id,'zh-CN',{numeric:true}));
 const size=6,max=Math.max(1,Math.ceil(filtered.length/size)),page=Math.max(1,Math.min(max,Number(ui().monitorDevicePage)||1));ui().monitorDevicePage=page;
 const subset=filtered.slice((page-1)*size,page*size),hasFilters=query||online!=='all'||status!=='all';
 return '<div class="mp-region-layout">'+tree()+'<section class="mp-region-main"><header class="mp-region-heading"><h1>区域设备 <span>/</span><small>海南省'+(region==='all'?'':' / '+e(region))+(district?' / '+e(district.name):'')+'</small></h1><div class="mp-header-actions">'+button(ico('rotate-cw',21)+'重置筛选','data-mon-clear','mp-quiet')+button(ico(ui().monitorAutoplay?'pause':'play',20)+(ui().monitorAutoplay?'暂停轮播':'轮播已暂停'),'data-mon-autoplay aria-pressed="'+!!ui().monitorAutoplay+'"','mp-quiet')+'</div></header><div class="mp-region-summary"><div class="mp-summary-label">当前区域</div>'+[['总数',stats.total,'total'],['运行',stats.running,'running'],['停止',stats.stopped,'stopped'],['未知',stats.unknown,'unknown'],['故障',stats.fault,'fault'],['离线',stats.offline,'offline']].map(([label,n,key])=>'<div class="mp-summary-item '+key+'"><span>'+label+'</span><strong '+(key==='total'?'data-mon-region-total="'+n+'" data-region-total="'+n+'"':'')+'>'+n+'</strong></div>').join('')+'</div><form id="mon-filter-form" class="mp-filter-bar"><label class="mp-search">'+ico('search',23)+'<input name="search" value="'+e(ui().monitorSearch||'')+'" placeholder="搜索编号、名称、所属人或位置" aria-label="搜索设备或所属人" autocomplete="off">'+(query?button(ico('x',18),'data-mp-clear-search aria-label="清空关键词"','mp-input-clear'):'')+'</label><select name="running" aria-label="运行或故障状态">'+[['all','全部状态'],['running','运行中'],['stopped','已停止'],['unknown','状态未知'],['fault','故障设备']].map(([key,label])=>'<option value="'+key+'" '+(status===key?'selected':'')+'>'+label+'</option>').join('')+'</select><select name="online" aria-label="连接状态">'+[['all','全部连接'],['online','通信在线'],['offline','通信离线']].map(([key,label])=>'<option value="'+key+'" '+(online===key?'selected':'')+'>'+label+'</option>').join('')+'</select><button class="mp-button mp-search-submit" type="submit">查询</button><span class="mp-sort">'+ico('arrow-down-wide-narrow',19)+'编号排序</span></form><div class="mp-filter-count"><span>筛选结果 <strong data-mon-filter-total="'+filtered.length+'" data-filter-count="'+filtered.length+'">'+filtered.length+'</strong> 台</span>'+(hasFilters?'<small>'+e(district?district.name:region==='all'?'海南省':region)+(query?' · '+e(ui().monitorSearch):'')+'</small>':'<small>通信、运行与故障分别统计</small>')+'</div><div class="mp-device-grid">'+(subset.length?subset.map(card).join(''):'<div class="mp-empty"><div class="mp-empty-icon">'+ico('search',82)+'</div><h2>没有匹配的设备</h2><p>'+e(district?district.name:region==='all'?'海南省':region)+(query?' · '+e(ui().monitorSearch):'')+'</p>'+button('清除筛选','data-mon-clear','mp-outline')+'</div>')+'</div><footer class="mp-pagination"><span>'+(filtered.length?'显示 '+((page-1)*size+1)+'–'+Math.min(page*size,filtered.length)+' 条，共 '+filtered.length+' 条':'0 条结果')+'</span><div>'+button(ico('chevron-left',23),'data-mon-page="'+(page-1)+'" aria-label="上一页" '+(page<=1||!filtered.length?'disabled':''),'mp-page-arrow')+'<strong data-mon-current-page="'+page+'" data-current-page="'+page+'">'+page+'</strong><span>/ '+max+'</span>'+button(ico('chevron-right',23),'data-mon-page="'+(page+1)+'" aria-label="下一页" '+(page>=max||!filtered.length?'disabled':''),'mp-page-arrow')+'</div></footer></section></div>';
}
function chart(d,key,hours){
 const meta=metrics[key]||metrics.hz,end=Date.parse(state().now),start=end-hours*3600000,last=Date.parse(d.lastSeen),validEnd=d.online?end:Math.min(end,Number.isFinite(last)?last:start);
 const raw=Demo.history(d.id,key,hours),series=raw.filter(p=>(d.online||Number.isFinite(last))&&finite(p.value)&&Number.isFinite(Date.parse(p.time))&&Date.parse(p.time)>=start&&Date.parse(p.time)<=validEnd);
 if(!d.online&&Number.isFinite(last)&&finite(d[key])&&validEnd>=start&&validEnd<=end&&!series.some(p=>Date.parse(p.time)===validEnd))series.push({time:new Date(validEnd).toISOString(),value:Number(d[key])});
 const mobile=window.innerWidth<760,w=mobile?600:window.innerWidth<1350?800:1200,h=mobile?300:240,p={l:mobile?46:60,r:mobile?16:28,t:26,b:mobile?40:46},plotW=w-p.l-p.r,plotH=h-p.t-p.b;
 const values=series.map(v=>Number(v.value));let low=values.length?Math.min(...values):0,high=values.length?Math.max(...values):key==='hz'?50:100;const padding=Math.max((high-low)*.22,high*.05,1);low=Math.max(0,low-padding);high+=padding;
 const x=t=>p.l+Math.max(0,Math.min(1,(Date.parse(t)-start)/(end-start)))*plotW,y=v=>p.t+(high-Number(v))/(high-low)*plotH;
 let grid='',labels='';for(let i=0;i<5;i++){const gy=p.t+plotH*i/4;grid+='<line x1="'+p.l+'" y1="'+gy+'" x2="'+(w-p.r)+'" y2="'+gy+'"/>';labels+='<text x="'+(p.l-13)+'" y="'+(gy+6)+'" text-anchor="end">'+number(high-(high-low)*i/4,key==='hz'||key==='current'?1:0)+'</text>';}
 for(let i=0;i<5;i++){const stamp=new Date(start+(end-start)*i/4).toISOString(),gx=p.l+plotW*i/4;grid+='<line x1="'+gx+'" y1="'+p.t+'" x2="'+gx+'" y2="'+(h-p.b)+'"/>';let label=shortTime(stamp).slice(0,5);if(hours>24)label=App.time(stamp).slice(5,10)+' '+label;labels+='<text x="'+gx+'" y="'+(h-13)+'" text-anchor="'+(i===0?'start':i===4?'end':'middle')+'">'+e(label)+'</text>';}
 const seriesPath=series.map((v,i)=>(i?'L':'M')+x(v.time).toFixed(2)+','+y(v.value).toFixed(2)).join(' '),lastPoint=series.at(-1),lastX=lastPoint?x(lastPoint.time):p.l;
 const gapStart=!d.online?Math.max(p.l,Math.min(w-p.r,p.l+(validEnd-start)/(end-start)*plotW)):w-p.r,gapWidth=Math.max(0,w-p.r-gapStart);
 const gap=!d.online?'<g data-history-gap="true" data-last-valid-time="'+e(d.lastSeen||'')+'"><rect data-mon-offline-gap="true" data-history-gap="true" x="'+gapStart.toFixed(2)+'" y="'+p.t+'" width="'+gapWidth.toFixed(2)+'" height="'+plotH+'" fill="url(#mp-gap-pattern)" stroke="#235a88" stroke-dasharray="5 5"/>'+(gapWidth>115?'<text x="'+(gapStart+gapWidth/2)+'" y="'+(p.t+plotH*.6)+'" class="mp-gap-text" text-anchor="middle">无新数据</text>':'<text x="'+(w-p.r)+'" y="'+(p.t-9)+'" class="mp-gap-small" text-anchor="end">无新数据</text>')+'</g>':'';
 const line=series.length?'<path data-mon-series="true" data-last-valid-time="'+e(lastPoint.time)+'" data-valid-point-count="'+series.length+'" data-last-x="'+lastX.toFixed(2)+'" d="'+seriesPath+'" fill="none" stroke="#0fe3ed" stroke-width="3"/>'+series.map((v,i)=>i%4===0||i===series.length-1?'<circle cx="'+x(v.time).toFixed(2)+'" cy="'+y(v.value).toFixed(2)+'" r="'+(i===series.length-1?5:3)+'" fill="#20e8ee" stroke="#98f6ff" stroke-width="'+(i===series.length-1?2:0)+'"><title>'+e(time(v.time))+' · '+number(v.value,meta.digits)+' '+meta.unit+'</title></circle>':'').join(''):'<text x="'+(p.l+plotW/2)+'" y="'+(p.t+plotH*.5)+'" text-anchor="middle" class="mp-gap-text">所选时间内无有效数据</text>';
 const area=series.length>1?'<path d="'+seriesPath+' L'+lastX.toFixed(2)+','+(h-p.b)+' L'+x(series[0].time).toFixed(2)+','+(h-p.b)+' Z" fill="url(#mp-chart-fill)"/>':'';
 return '<div class="mp-chart-wrap"><span class="mp-chart-unit">'+meta.unit+'</span><svg class="mp-history-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+meta.label+'演示趋势'+(!d.online?'，在最后有效数据后留空':'')+'"><defs><linearGradient id="mp-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#02d5e8" stop-opacity=".23"/><stop offset="1" stop-color="#02d5e8" stop-opacity=".02"/></linearGradient><pattern id="mp-gap-pattern" width="11" height="11" patternUnits="userSpaceOnUse"><path d="M-3 3L3-3M0 11L11 0M8 14L14 8" stroke="#17639a" stroke-width="1"/></pattern></defs><g class="mp-chart-grid">'+grid+'</g>'+gap+area+line+'<g class="mp-chart-labels">'+labels+'</g></svg><div class="mp-chart-caption"><span>'+ico('info',15)+'合成历史仅用于 Demo；缺测不补零、不延长曲线。</span>'+(!d.online?'<strong>最后有效 '+e(shortTime(d.lastSeen))+'</strong>':'')+'</div></div>';
}
function recentEvents(d){
 const events=[];
 state().alarms.filter(a=>a.deviceId===d.id).forEach(a=>{events.push({time:a.createdAt,text:a.message||a.kind,type:'alarm'});if(a.ackAt)events.push({time:a.ackAt,text:'报警已确认：'+(a.message||a.kind),type:'ack'});if(a.resolvedAt)events.push({time:a.resolvedAt,text:'状态已恢复：'+(a.message||a.kind),type:'recovered'});});
 state().commands.filter(c=>c.deviceId===d.id).forEach(c=>events.push({time:c.completedAt||c.createdAt,text:({start:'启动',stop:'停止',frequency:'设置频率',reset:'故障复位'})[c.action]+' · '+({pending:'等待回执',succeeded:'执行成功',failed:'执行失败',uncertain:'结果未知'})[c.status],type:'command'}));
 if(!d.online)events.push({time:d.lastSeen,text:d.lastSeen?'此时间后未收到有效采样，当前运行状态未知':'尚无有效采样，当前运行状态未知',type:'offline'});
 return chronological(events).slice(0,4);
}
function detail(){
 const d=selected();if(!d)return '<div class="mp-empty"><h2>暂无设备</h2>'+button('返回区域设备','data-mon-nav="region"')+'</div>';
 ui().deviceId=d.id;const metric=metrics[ui().monitorMetric]?ui().monitorMetric:'hz',hours=[1,24,168].includes(Number(ui().monitorHours))?Number(ui().monitorHours):24,tab=ui().monitorDetailTab||'history';
 const c=effective(d.id),local=Demo.contract(d.id),waiting=!!local&&(!c||local.end!==c.end||local.start!==c.start),lease=Demo.lease(d.id),alarms=chronological(state().alarms.filter(a=>a.deviceId===d.id)),active=alarms.filter(a=>!a.resolvedAt),faultAlarm=active.find(a=>a.kind==='fault')||active[0],events=recentEvents(d);
 const alarmTitle=d.fault?String(d.fault):d.online&&faultAlarm?faultAlarm.message:'';
 return '<div class="mp-detail-layout"><aside class="mp-device-sidebar">'+button(ico('chevron-left',24)+(ui().monitorDetailReturn==='map'?'返回区域地图':'返回区域设备'),'data-mon-nav="'+(ui().monitorDetailReturn==='map'?'map':'region')+'"','mp-return')+'<div class="mp-device-breadcrumb">'+e(d.region||'未分类')+' / '+e(d.id)+'</div><div class="mp-device-name"><h1>'+e(d.name)+'</h1>'+pill(d.fault?'故障':!d.online?'离线':runText(d),d.fault?'fault':!d.online?'offline':run(d))+'</div><div class="mp-device-connection '+(!d.online?'offline':'')+'"><i></i>'+e(d.online?'通信在线 · 数据为演示采样':'通信离线 · 当前状态未知')+'</div>'+(!d.online?'<div class="mp-sidebar-warning">'+ico('triangle-alert',23)+'设备离线 · 运行状态未知</div><p class="mp-last-seen">最后有效数据 '+e(shortTime(d.lastSeen))+'</p>':'')+section('设备资料')+'<dl class="mp-device-info"><dt>编号</dt><dd>'+e(d.id)+'</dd><dt>所属人</dt><dd>'+e(owner(d))+'</dd><dt>所属区域</dt><dd>'+e(d.region||'未分类')+'</dd><dt>安装位置</dt><dd>'+e(d.place||'未登记')+'</dd><dt>最后测量</dt><dd>'+e(time(d.lastSeen))+'</dd><dt>4G 模块</dt><dd class="mp-module-id">'+e(d.module)+'</dd></dl>'+section('基本参数')+'<dl class="mp-device-info"><dt>厂商</dt><dd>'+e(d.vendor)+'</dd><dt>型号</dt><dd>'+e(d.model)+'</dd><dt>额定功率</dt><dd>—</dd><dt>额定电压</dt><dd>—</dd></dl><div class="mp-meta-note">'+ico('info',17)+'未提供的型号参数不作推断</div><div class="mon-lease-summary mp-lease-summary"><div><span>云端生效到期</span><strong>'+e(c?time(c.end):'未登记')+'</strong></div>'+(waiting?'<div><span>本地已登记到期</span><strong>'+e(time(local.end))+'</strong></div><small>新租期等待同步</small>':'')+'<div class="mp-lease-state">'+e(lease.label)+'</div>'+button('查看合同与租期 '+ico('chevron-right',15),'data-mon-lease="'+e(d.id)+'"','mp-lease-link')+'</div></aside><section class="mp-detail-main">'+(alarmTitle?'<div class="mp-detail-alert '+(d.fault?'fault':'warning')+'">'+ico('triangle-alert',30)+'<strong>'+e(alarmTitle)+'</strong><span>'+e(faultAlarm?.ackAt?'已确认':'待确认')+' · 尚未恢复</span><small>'+e(shortTime(faultAlarm?.createdAt||d.lastSeen))+' 发生</small></div>':'')+(!d.online?section('最后有效读数','<small>时间 '+e(shortTime(d.lastSeen))+'</small>'):'')+'<div class="mp-readings">'+Object.entries(metrics).map(([key,m])=>'<div class="mp-reading" data-mon-reading="'+key+'" data-history="'+(!d.online)+'"><span>'+m.label+'</span><strong>'+number(d[key],m.digits)+'<small>'+m.unit+'</small></strong>'+(!d.online?'<em>历史值</em>':'')+'</div>').join('')+'</div><div class="mp-history-toolbar"><div class="mp-detail-tabs">'+button('实时参数','data-mp-tab="live"',tab==='live'?'active':'')+button('历史趋势','data-mp-tab="history"',tab==='history'?'active':'')+'</div><div class="mp-time-segments">'+[[1,'1小时'],[24,'24小时'],[168,'7天']].map(([n,label])=>button(label,'data-mon-hours="'+n+'" aria-pressed="'+(hours===n)+'"',hours===n?'active':'')).join('')+'</div></div>'+(tab==='history'?'<div class="mp-metric-title">'+section(metrics[metric].label+'趋势')+'<div class="mp-metric-segments">'+Object.entries(metrics).map(([key,m])=>button(m.label.replace('输出',''),'data-mon-metric="'+key+'" aria-pressed="'+(metric===key)+'"',metric===key?'active':'')).join('')+'</div></div>'+chart(d,metric,hours):'<div class="mp-live-table"><div><span>参数名称</span><span>有效读数</span><span>数据说明</span></div>'+Object.entries(metrics).map(([key,m])=>'<div><strong>'+m.label+'</strong><span>'+number(d[key],m.digits)+' '+m.unit+'</span><span>'+(!d.online?'历史值 · '+e(shortTime(d.lastSeen)):'最近采样 · '+e(shortTime(d.lastSeen)))+'</span></div>').join('')+'</div>')+'<section class="mp-events">'+section('最近事件')+'<div>'+(events.length?events.map(event=>'<div class="mp-event '+event.type+'"><time>'+e(shortTime(event.time))+'</time><span>'+e(event.text)+'</span></div>').join(''):'<div class="mp-event quiet">暂无相关故障与指令事件</div>')+'</div></section></section></div>';
}
function alarms(){
 const filter=ui().monitorAlarmFilter||'all',did=ui().monitorAlarmDevice||'all',all=state().alarms;
 const filtered=chronological(all.filter(a=>(did==='all'||a.deviceId===did)&&(filter==='all'||filter==='open'&&!a.resolvedAt||filter==='unack'&&!a.ackAt||filter==='resolved'&&!!a.resolvedAt)));
 return '<section class="mp-alarm-page"><header class="mp-region-heading"><h1>报警记录 <span>/</span><small>海南省</small></h1><div class="mp-alarm-counts"><span>未确认 <strong>'+all.filter(a=>!a.ackAt).length+'</strong></span><span>未恢复 <strong>'+all.filter(a=>!a.resolvedAt).length+'</strong></span></div></header><div class="mp-alarm-toolbar"><div class="mp-alarm-tabs">'+[['all','全部记录'],['unack','未确认'],['open','未恢复'],['resolved','已恢复']].map(([key,label])=>button(label,'data-mon-alarm-filter="'+key+'"',filter===key?'active':'')).join('')+'</div><select data-mon-alarm-device aria-label="筛选报警设备"><option value="all">全部设备</option>'+state().devices.map(d=>'<option value="'+e(d.id)+'" '+(did===d.id?'selected':'')+'>'+e(d.name)+'</option>').join('')+'</select></div><div class="mp-alarm-note">'+ico('info',19)+'确认表示已知晓；故障恢复由设备状态决定。确认报警不会清除设备故障。</div><p class="mp-table-scroll-note">左右滑动查看确认、恢复时间与操作</p><div class="mp-alarm-table-wrap"><table class="mp-alarm-table"><thead><tr><th>设备 / 报警内容</th><th>类型</th><th>发生时间</th><th>确认状态</th><th>恢复状态</th><th>操作</th></tr></thead><tbody>'+filtered.map(a=>{
  const d=state().devices.find(x=>x.id===a.deviceId),kind=({fault:'设备故障',offline:'通信离线',lease:'租期到期'})[a.kind]||a.kind||'设备事件';
  return '<tr data-mon-alarm-id="'+e(a.id)+'"><td><strong>'+e(a.message||kind)+'</strong>'+button(e(d?d.name:a.deviceId)+' · '+e(a.deviceId),'data-mon-detail="'+e(a.deviceId)+'"','mp-table-device')+'</td><td>'+pill(kind,a.kind==='fault'?'fault':'warning')+'</td><td>'+e(time(a.createdAt))+'</td><td>'+pill(a.ackAt?'已确认':'待确认',a.ackAt?'quiet':'warning')+(a.ackAt?'<small>'+e(time(a.ackAt))+'</small>':'')+'</td><td>'+pill(a.resolvedAt?'已恢复':'尚未恢复',a.resolvedAt?'running':'fault')+(a.resolvedAt?'<small>'+e(time(a.resolvedAt))+'</small>':'')+'</td><td>'+button(a.ackAt?'已确认':'确认报警','data-mon-ack="'+e(a.id)+'" '+(a.ackAt?'disabled':''),'mp-outline')+'</td></tr>';
 }).join('')+'</tbody></table></div>'+(filtered.length?'':'<div class="mp-empty mp-alarm-empty">'+ico('circle-check',62)+'<h2>没有符合条件的报警</h2><p>可调整设备或确认 / 恢复状态筛选。</p></div>')+'<div class="mp-alarm-footer">共 '+filtered.length+' 条记录<span>故障、通信与确认状态分别记录</span></div></section>';
}
function bind(container){
 container.querySelectorAll('[data-mp-expand]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();const key=b.dataset.mpExpand,current=ui().monitorTreeExpanded||{};current[key]=b.getAttribute('aria-expanded')!=='true';ui().monitorTreeExpanded=current;ui().monitorAutoplay=false;App.render();});
 container.querySelectorAll('[data-mp-tab]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();ui().monitorDetailTab=b.dataset.mpTab;App.render();});
 container.querySelectorAll('button[data-mon-hours]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();ui().monitorHours=Number(b.dataset.monHours);App.render();});
 container.querySelectorAll('[data-mp-clear-search]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();ui().monitorSearch='';ui().monitorDevicePage=1;ui().monitorAutoplay=false;App.render();});
}
globalThis.MonitorPages={regional,detail,alarms,bind};
})();


